package com.aoo.bcg.club;
import com.fasterxml.jackson.databind.ObjectMapper; import java.net.URI; import java.net.http.*; import java.time.Duration; import java.util.Map;
/** Production HTTP adapter to the authenticated room-authority ingress. */
public final class HttpRoomAuthorityPort implements ClubRoomKickCoordinator.RoomAuthorityPort {
 private final HttpClient http=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(3)).build(); private final URI endpoint; private final String token; private final ObjectMapper json;
 public HttpRoomAuthorityPort(URI endpoint,String token,ObjectMapper json){this.endpoint=endpoint;if(token==null||token.length()<32)throw new IllegalArgumentException("room authority token must contain 32 characters");this.token=token;this.json=json;}
 public long kick(ClubRoomKickCoordinator.Command c){try{byte[] body=json.writeValueAsBytes(Map.of("action","kick","roomId",c.roomId(),"seatId",c.actorSeatId(),"targetSeatId",c.targetSeatId(),"playVersion",c.playVersion(),"stateVersion",c.stateVersion()));HttpRequest q=HttpRequest.newBuilder(endpoint).timeout(Duration.ofSeconds(8)).header("Authorization","Bearer "+token).header("Idempotency-Key",c.requestId()).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofByteArray(body)).build();HttpResponse<byte[]>r=http.send(q,HttpResponse.BodyHandlers.ofByteArray());if(r.statusCode()<200||r.statusCode()>=300)throw new IllegalStateException("room authority rejected: HTTP "+r.statusCode());Object value=json.readValue(r.body(),Map.class).get("stateVersion");if(!(value instanceof Number n))throw new IllegalStateException("room authority response missing stateVersion");return n.longValue();}catch(InterruptedException x){Thread.currentThread().interrupt();throw new IllegalStateException("room authority interrupted",x);}catch(Exception x){throw x instanceof IllegalStateException i?i:new IllegalStateException("room authority unavailable",x);}}
}
